import{_ as e,o as t,c as r,af as o}from"./chunks/framework.BmOFhHdK.js";const p=JSON.parse('{"title":"图解工作法","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/2024/202401-illustrations.md","filePath":"blogs/2024/202401-illustrations.md","lastUpdated":1772894295000}'),l={name:"blogs/2024/202401-illustrations.md"};function i(s,a,h,d,c,n){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="图解工作法" tabindex="-1">图解工作法 <a class="header-anchor" href="#图解工作法" aria-label="Permalink to &quot;图解工作法&quot;">​</a></h1><p>去年在<a href="./../2023/202304-draw-architecture-diagram">架构图怎么画</a>中总结了架构图的绘制方法之后，我开始思考如何将图的方式应用到更多的场景中，比如学习和生活中。</p><p>随着绘图技能的熟练度增加，我发现不同的图其实就是不同的思维工具。比如，思维导图就是逻辑树的一种实现，将问题分解为子问题，再递归分解，直到得到可解的小问题。再比如，时序图则以时间为轴，描述了多个主体之间的事件发生顺序和关系，用来进行推理断案（剧本杀）也是不错的选择。</p><h2 id="图解-可视化思维模式" tabindex="-1">图解：可视化思维模式 <a class="header-anchor" href="#图解-可视化思维模式" aria-label="Permalink to &quot;图解：可视化思维模式&quot;">​</a></h2><p>相比不可言说的大脑内的思维运转，用图来表现和记录你的思考过程，可以更加清晰和直观。不仅可以帮助你日后回顾和整理，还能帮助他人理解你的思考过程。</p><p>得益于现在丰富的绘图工具和图例，白板、版本化、代码化、图层 ... 绘制一些简单的图甚至比打字更快</p><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><p>话虽如此，想要将图解工作法应用到更多的场景中，还需要一些方法论和实践。先思考，再输出，图解只是一种输出形式。</p><h3 id="复现" tabindex="-1">复现 <a class="header-anchor" href="#复现" aria-label="Permalink to &quot;复现&quot;">​</a></h3><p>将脑中的信息“抛”到白板上</p><blockquote><p>类似头脑风暴，将所有的信息都记录下来，不做筛选 <br> 可以释放大脑内存，便于后续思考</p></blockquote><h3 id="发散" tabindex="-1">发散 <a class="header-anchor" href="#发散" aria-label="Permalink to &quot;发散&quot;">​</a></h3><p>对当前的信息进行发散</p><ul><li>是否有遗漏的信息</li><li>是否有补充的说明</li><li>信息间是否存在关联，时间先后、依赖、组成</li></ul><blockquote><p>包括纳入外部信息，进行对比和参考 <br> 比如访谈、搜索</p></blockquote><h3 id="收敛" tabindex="-1">收敛 <a class="header-anchor" href="#收敛" aria-label="Permalink to &quot;收敛&quot;">​</a></h3><p>聚焦关键信息进行整理</p><ul><li>语义收敛：使用简称、符号、颜色来表达信息的种类和内容</li><li>逻辑收敛：通过距离、方向、形状来表达信息的关系和结构</li><li>找出关键信息</li></ul><blockquote><p>通过这一步可以精炼信息，减少冗余 <br> 也会迫使你对信息再进行一次思考和检索</p></blockquote><h3 id="重组" tabindex="-1">重组 <a class="header-anchor" href="#重组" aria-label="Permalink to &quot;重组&quot;">​</a></h3><p>以收敛后的关键信息为中心，选择合适的图例重新绘制图</p><blockquote><p>收敛之后你就知道你需要什么样的图来表达你的思考 <br> 也可以根据图的特性来进一步思考</p></blockquote><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><blockquote><p>diagrams tools: <a href="https://github.com/Anddd7/docs-architecture-diagrams" target="_blank" rel="noreferrer">https://github.com/Anddd7/docs-architecture-diagrams</a></p></blockquote>',24)])])}const b=e(l,[["render",i]]);export{p as __pageData,b as default};
